import math

def _get_joints(agent_components):
    if isinstance(agent_components, dict):
        return agent_components.get("joints", [])
    return []

def build_agent(sandbox):
    # Lightweight torso with minimal mass
    torso = sandbox.add_beam(x=10.0, y=2.0, width=0.2, height=0.2, density=1.0)

    # Add two wheels with optimal placement for traction and low mass
    wheel_radius = 0.25  # Slightly larger radius for better contact
    wheel_density = 0.5  # Low density to keep mass low

    # Position wheels at ground level (y=1.0 + radius)
    wheel1 = sandbox.add_wheel(x=9.5, y=1.0 + wheel_radius, radius=wheel_radius, density=wheel_density)
    wheel2 = sandbox.add_wheel(x=10.5, y=1.0 + wheel_radius, radius=wheel_radius, density=wheel_density)

    # Connect wheels to torso with pivot joints allowing full rotation
    joint1 = sandbox.add_joint(torso, wheel1, (9.5, 1.0 + wheel_radius), type='pivot', lower_limit=-math.pi, upper_limit=math.pi)
    joint2 = sandbox.add_joint(torso, wheel2, (10.5, 1.0 + wheel_radius), type='pivot', lower_limit=-math.pi, upper_limit=math.pi)

    # Set high friction for better traction (within friction cap constraints)
    sandbox.set_material_properties(wheel1, friction=1.0)
    sandbox.set_material_properties(wheel2, friction=1.0)

    return {"body": torso, "joints": [joint1, joint2]}

def agent_action(sandbox, agent_body, step_count):
    joints = _get_joints(agent_body)
    for i, j in enumerate(joints):
        if i == 0:
            motor_speed = -5.0  # Left wheel turns clockwise
        else:
            motor_speed = 5.0   # Right wheel turns counterclockwise
        sandbox.set_motor(j, motor_speed, max_torque=100.0)
